ParsedInput parse_input(const std::string &input) {
    auto ret = uniffi::rust_call(
        uniffi_glsdk_fn_func_parse_input,
        uniffi::FfiConverterError::lift, uniffi::FfiConverterString::lower(input));

    return uniffi::FfiConverterParsedInput::lift(ret);
}


ResolvedInput resolve_input(const std::string &input) {
    auto ret = uniffi::rust_call(
        uniffi_glsdk_fn_func_resolve_input,
        uniffi::FfiConverterError::lift, uniffi::FfiConverterString::lower(input));

    return uniffi::FfiConverterResolvedInput::lift(ret);
}

void set_log_level(const LogLevel &level) {
    uniffi::rust_call(
        uniffi_glsdk_fn_func_set_log_level,
        nullptr, uniffi::FfiConverterLogLevel::lower(level));
}

void set_logger(const LogLevel &level, const std::shared_ptr<LogListener> &listener) {
    uniffi::rust_call(
        uniffi_glsdk_fn_func_set_logger,
        uniffi::FfiConverterError::lift, uniffi::FfiConverterLogLevel::lower(level), uniffi::FfiConverterLogListener::lower(listener));
}
